"""
REST API for model_generation package.

Provides HTTP endpoints for URDF generation, conversion, editing, and library access.
Can be used with Flask, FastAPI, or other frameworks via adapters.
"""

from __future__ import annotations

import logging
import os
import time
from collections.abc import Callable
from dataclasses import dataclass, field
from enum import Enum
from typing import Any

from .generation_handlers import GenerationHandlersMixin as _GenerationHandlersMixin
from .library_handlers import LibraryHandlersMixin as _LibraryHandlersMixin

logger = logging.getLogger(__name__)


class HTTPMethod(Enum):
    """HTTP methods."""

    GET = "GET"
    POST = "POST"
    PUT = "PUT"
    DELETE = "DELETE"
    PATCH = "PATCH"


@dataclass
class APIRequest:
    """Abstraction for HTTP request."""

    method: HTTPMethod
    path: str
    query_params: dict[str, str] = field(default_factory=dict)
    body: dict[str, Any] | None = None
    files: dict[str, bytes] = field(default_factory=dict)
    headers: dict[str, str] = field(default_factory=dict)


@dataclass
class APIResponse:
    """Abstraction for HTTP response."""

    status_code: int
    body: dict[str, Any] | str | bytes
    content_type: str = "application/json"
    headers: dict[str, str] = field(default_factory=dict)

    @classmethod
    def ok(cls, data: dict[str, Any]) -> APIResponse:
        """Create a 200 OK response with *data* as the JSON body."""
        return cls(status_code=200, body=data)

    @classmethod
    def created(cls, data: dict[str, Any]) -> APIResponse:
        """Create a 201 Created response with *data* as the JSON body."""
        return cls(status_code=201, body=data)

    @classmethod
    def error(cls, message: str, status_code: int = 400) -> APIResponse:
        """Create an error response with the given *status_code* (default 400)."""
        return cls(status_code=status_code, body={"error": message})

    @classmethod
    def not_found(cls, message: str = "Not found") -> APIResponse:
        """Create a 404 Not Found response with *message*."""
        return cls(status_code=404, body={"error": message})

    @classmethod
    def file(
        cls,
        content: str | bytes,
        filename: str,
        content_type: str = "application/xml",
    ) -> APIResponse:
        """Create a file-download response with a Content-Disposition header."""
        return cls(
            status_code=200,
            body=content if isinstance(content, bytes) else content.encode(),
            content_type=content_type,
            headers={
                "Content-Disposition": f'attachment; filename="{filename}"',
            },
        )


@dataclass
class Route:
    """API route definition."""

    method: HTTPMethod
    path: str
    handler: Callable[[APIRequest], APIResponse]
    description: str = ""
    tags: list[str] = field(default_factory=list)


class ModelGenerationAPI(
    _GenerationHandlersMixin,
    _LibraryHandlersMixin,
):
    """
    REST API for model generation operations.

    Handler methods are provided by mixins (see generation_handlers.py
    and library_handlers.py) to keep this orchestrator class focused on
    routing and middleware concerns.

    Provides endpoints for:
    - URDF generation (parametric, humanoid)
    - Format conversion (SimScape, MJCF)
    - Model validation
    - Library operations
    - Inertia calculation

    Example with Flask:
        from flask import Flask, request, jsonify
        from model_generation.api import ModelGenerationAPI, FlaskAdapter

        app = Flask(__name__)
        api = ModelGenerationAPI()
        FlaskAdapter(api).register(app)

    Example with FastAPI:
        from fastapi import FastAPI
        from model_generation.api import ModelGenerationAPI, FastAPIAdapter

        app = FastAPI()
        api = ModelGenerationAPI()
        FastAPIAdapter(api).register(app)
    """

    def __init__(self, prefix: str = "/api/v1") -> None:
        """
        Initialize API.

        Args:
            prefix: URL prefix for all routes
        """
        if prefix is None:
            raise ValueError("prefix must be provided")
        self.prefix = prefix
        self._routes: list[Route] = []

        # Security configuration from environment
        self._api_key: str | None = os.environ.get("MODEL_GEN_API_KEY")
        self._cors_origins: str = os.environ.get("MODEL_GEN_CORS_ORIGINS", "")
        self._rate_limit: int | None = None
        rate_limit_str = os.environ.get("MODEL_GEN_RATE_LIMIT")
        if rate_limit_str:
            try:
                self._rate_limit = int(rate_limit_str)
            except ValueError:
                logger.warning("Invalid MODEL_GEN_RATE_LIMIT value: %s", rate_limit_str)

        self._is_production: bool = (
            os.environ.get("MODEL_GEN_ENV", "").lower() == "production"
        )

        # In-memory sliding window rate limiter: client_ip -> list[timestamp]
        self._rate_limit_windows: dict[str, list[float]] = {}

        self._register_routes()

    def _register_core_routes(self) -> None:
        """Register health, generation, conversion, validation, and parsing routes."""
        self.add_route(HTTPMethod.GET, "/health", self.health_check, "Health check")
        self.add_route(HTTPMethod.GET, "/info", self.get_api_info, "API information")

        self.add_route(
            HTTPMethod.POST,
            "/generate/humanoid",
            self.generate_humanoid,
            "Generate humanoid URDF",
            ["generation"],
        )
        self.add_route(
            HTTPMethod.POST,
            "/generate/from-params",
            self.generate_from_params,
            "Generate URDF from parameters",
            ["generation"],
        )

        self.add_route(
            HTTPMethod.POST,
            "/convert/simscape-to-urdf",
            self.convert_simscape_to_urdf,
            "Convert SimScape to URDF",
            ["conversion"],
        )
        self.add_route(
            HTTPMethod.POST,
            "/convert/mjcf-to-urdf",
            self.convert_mjcf_to_urdf,
            "Convert MJCF to URDF",
            ["conversion"],
        )
        self.add_route(
            HTTPMethod.POST,
            "/convert/urdf-to-mjcf",
            self.convert_urdf_to_mjcf,
            "Convert URDF to MJCF",
            ["conversion"],
        )

        self.add_route(
            HTTPMethod.POST,
            "/validate",
            self.validate_urdf,
            "Validate URDF content",
            ["validation"],
        )
        self.add_route(
            HTTPMethod.POST,
            "/parse",
            self.parse_urdf,
            "Parse URDF and return structure",
            ["parsing"],
        )

    def _register_inertia_and_library_routes(self) -> None:
        """Register inertia calculation and library management routes."""
        self.add_route(
            HTTPMethod.POST,
            "/inertia/calculate",
            self.calculate_inertia,
            "Calculate inertia for shape",
            ["inertia"],
        )
        self.add_route(
            HTTPMethod.POST,
            "/inertia/from-mesh",
            self.inertia_from_mesh,
            "Calculate inertia from mesh file",
            ["inertia"],
        )

        self.add_route(
            HTTPMethod.GET,
            "/library/models",
            self.library_list_models,
            "List available models",
            ["library"],
        )
        self.add_route(
            HTTPMethod.GET,
            "/library/models/{model_id}",
            self.library_get_model,
            "Get model details",
            ["library"],
        )
        self.add_route(
            HTTPMethod.POST,
            "/library/models",
            self.library_add_model,
            "Add model to library",
            ["library"],
        )
        self.add_route(
            HTTPMethod.DELETE,
            "/library/models/{model_id}",
            self.library_remove_model,
            "Remove model from library",
            ["library"],
        )
        self.add_route(
            HTTPMethod.GET,
            "/library/models/{model_id}/download",
            self.library_download_model,
            "Download model URDF",
            ["library"],
        )

    def _register_editor_routes(self) -> None:
        """Register editor-related routes."""
        self.add_route(
            HTTPMethod.POST,
            "/editor/compose",
            self.compose_models,
            "Compose model from multiple sources",
            ["editor"],
        )
        self.add_route(
            HTTPMethod.POST,
            "/editor/diff",
            self.diff_urdfs,
            "Compare two URDF files",
            ["editor"],
        )

    def _register_routes(self) -> None:
        """Register all API routes."""
        self._register_core_routes()
        self._register_inertia_and_library_routes()
        self._register_editor_routes()

    def add_route(
        self,
        method: HTTPMethod,
        path: str,
        handler: Callable[[APIRequest], APIResponse],
        description: str = "",
        tags: list[str] | None = None,
    ) -> None:
        """Add a route to the API."""
        self._routes.append(
            Route(
                method=method,
                path=self.prefix + path,
                handler=handler,
                description=description,
                tags=tags or [],
            )
        )

    def get_routes(self) -> list[Route]:
        """Get all registered routes."""
        return self._routes

    def _check_api_key(self, request: APIRequest) -> APIResponse | None:
        """Check API key authentication if MODEL_GEN_API_KEY is set.

        Returns None if auth passes, or a 401 APIResponse if auth fails.
        """
        if request is None:
            raise ValueError("request must be provided")
        if not self._api_key:
            return None  # No API key configured, skip auth
        provided_key = request.headers.get("X-API-Key")
        if not provided_key or provided_key != self._api_key:
            return APIResponse.error("Unauthorized: invalid or missing API key", 401)
        return None

    def _check_rate_limit(self, request: APIRequest) -> APIResponse | None:
        """Sliding window rate limiter.  Returns 429 if limit exceeded.

        Uses MODEL_GEN_RATE_LIMIT (requests per minute).  The client IP
        is extracted from the X-Forwarded-For header or defaults to
        "unknown".
        """
        if request is None:
            raise ValueError("request must be provided")
        if self._rate_limit is None:
            return None

        client_ip = (
            request.headers.get("X-Forwarded-For", "unknown").split(",")[0].strip()
        )
        now = time.time()
        window_start = now - 60.0  # 1-minute sliding window

        # Prune old entries
        timestamps = self._rate_limit_windows.setdefault(client_ip, [])
        self._rate_limit_windows[client_ip] = [
            ts for ts in timestamps if ts > window_start
        ]

        if len(self._rate_limit_windows[client_ip]) >= self._rate_limit:
            return APIResponse.error("Rate limit exceeded. Try again later.", 429)

        self._rate_limit_windows[client_ip].append(now)
        return None

    def _add_cors_headers(self, response: APIResponse) -> None:
        """Add CORS headers to response.

        The allowed origin is configured via the MODEL_GEN_CORS_ORIGINS
        environment variable (comma-separated list).  If not set, defaults
        to an empty string (no cross-origin access).
        """
        if response is None:
            raise ValueError("response must be provided")
        origin = self._cors_origins.split(",")[0].strip() if self._cors_origins else ""
        response.headers["Access-Control-Allow-Origin"] = origin
        response.headers["Access-Control-Allow-Methods"] = (
            "GET, POST, PUT, DELETE, OPTIONS"
        )
        response.headers["Access-Control-Allow-Headers"] = "Content-Type, X-API-Key"

    def _add_security_headers(self, response: APIResponse) -> None:
        """Add security headers to response."""
        if response is None:
            raise ValueError("response must be provided")
        response.headers["Content-Security-Policy"] = "default-src 'self'"
        response.headers["X-Content-Type-Options"] = "nosniff"
        response.headers["X-Frame-Options"] = "DENY"
        response.headers["Strict-Transport-Security"] = (
            "max-age=31536000; includeSubDomains"
        )

    def handle_request(self, request: APIRequest) -> APIResponse:  # noqa: C901
        """Handle an API request."""
        # Security pre-flight checks
        if request is None:
            raise ValueError("request must be provided")
        auth_error = self._check_api_key(request)
        if auth_error is not None:
            self._add_security_headers(auth_error)
            self._add_cors_headers(auth_error)
            return auth_error

        rate_error = self._check_rate_limit(request)
        if rate_error is not None:
            self._add_security_headers(rate_error)
            self._add_cors_headers(rate_error)
            return rate_error

        # Find matching route
        for route in self._routes:
            if route.method != request.method:
                continue

            # Simple path matching (handles {param} patterns)
            route_parts = route.path.split("/")
            request_parts = request.path.split("/")

            if len(route_parts) != len(request_parts):
                continue

            params = {}
            match = True
            for rp, reqp in zip(route_parts, request_parts, strict=False):
                if rp.startswith("{") and rp.endswith("}"):
                    param_name = rp[1:-1]
                    params[param_name] = reqp
                elif rp != reqp:
                    match = False
                    break

            if match:
                # Add path params to query params
                request.query_params.update(params)
                try:
                    response = route.handler(request)
                    self._add_security_headers(response)
                    self._add_cors_headers(response)
                    return response
                except Exception as e:  # noqa: BLE001
                    logger.exception("Error handling request")
                    response = APIResponse.error(str(e), 500)
                    self._add_security_headers(response)
                    self._add_cors_headers(response)
                    return response

        response = APIResponse.not_found(
            f"No route for {request.method.value} {request.path}"
        )
        self._add_security_headers(response)
        self._add_cors_headers(response)
        return response

    # ============================================================
    # Health/Info Handlers
    # ============================================================

    def health_check(self, request: APIRequest) -> APIResponse:
        """Health check endpoint."""
        return APIResponse.ok({"status": "healthy", "service": "model_generation"})

    def get_api_info(self, request: APIRequest) -> APIResponse:
        """Get API information."""
        return APIResponse.ok(
            {
                "name": "Model Generation API",
                "version": "1.0.0",
                "description": "REST API for URDF generation, conversion, and manipulation",
                "endpoints": [
                    {
                        "method": r.method.value,
                        "path": r.path,
                        "description": r.description,
                        "tags": r.tags,
                    }
                    for r in self._routes
                ],
            }
        )

    # ============================================================
    # Handler methods are provided by GenerationHandlersMixin and
    # LibraryHandlersMixin (see generation_handlers.py and
    # library_handlers.py).
    # ============================================================


# ============================================================
# Framework Adapters
# ============================================================


class FlaskAdapter:
    """Adapter for Flask framework."""

    def __init__(self, api: ModelGenerationAPI) -> None:
        if api is None:
            raise ValueError("api must be provided")
        self.api = api

    def register(self, app: Any) -> None:
        """Register routes with Flask app."""
        from flask import jsonify, make_response
        from flask import request as flask_request

        for route in self.api.get_routes():
            endpoint = route.path.replace("/", "_").replace("{", "").replace("}", "")

            def make_handler(r: Route) -> Callable[..., Any]:
                def handler(**kwargs: Any) -> Any:
                    # Build APIRequest
                    api_request = APIRequest(
                        method=HTTPMethod(flask_request.method),
                        path=flask_request.path,
                        query_params={**flask_request.args, **kwargs},
                        body=flask_request.get_json(silent=True),
                        files={k: v.read() for k, v in flask_request.files.items()},
                        headers=dict(flask_request.headers),
                    )

                    response = self.api.handle_request(api_request)

                    if isinstance(response.body, bytes):
                        flask_response = make_response(response.body)
                    elif isinstance(response.body, dict):
                        flask_response = make_response(jsonify(response.body))
                    else:
                        flask_response = make_response(response.body)

                    flask_response.status_code = response.status_code
                    flask_response.content_type = response.content_type

                    for k, v in response.headers.items():
                        flask_response.headers[k] = v

                    return flask_response

                return handler

            # Convert path params from {param} to <param>
            flask_path = route.path.replace("{", "<").replace("}", ">")
            app.add_url_rule(
                flask_path,
                endpoint=endpoint,
                view_func=make_handler(route),
                methods=[route.method.value],
            )


class FastAPIAdapter:
    """Adapter for FastAPI framework."""

    def __init__(self, api: ModelGenerationAPI) -> None:
        if api is None:
            raise ValueError("api must be provided")
        self.api = api

    def register(self, app: Any) -> None:
        """Register routes with FastAPI app."""
        from fastapi import Request, Response
        from fastapi.responses import JSONResponse

        for route in self.api.get_routes():

            async def make_handler(r: Route) -> Callable[..., Any]:
                async def handler(request: Request, **kwargs: Any) -> Any:
                    body = None
                    try:
                        body = await request.json()
                    except (ValueError, UnicodeDecodeError) as e:
                        logger.debug("Failed to parse request JSON body: %s", e)

                    files = {}
                    form = await request.form()
                    for key, value in form.items():
                        if hasattr(value, "read"):
                            files[key] = await value.read()

                    api_request = APIRequest(
                        method=HTTPMethod(request.method),
                        path=request.url.path,
                        query_params={**request.query_params, **kwargs},
                        body=body,
                        files=files,
                        headers=dict(request.headers),
                    )

                    response = self.api.handle_request(api_request)

                    if isinstance(response.body, bytes):
                        return Response(
                            content=response.body,
                            status_code=response.status_code,
                            media_type=response.content_type,
                            headers=response.headers,
                        )
                    return JSONResponse(
                        content=response.body,
                        status_code=response.status_code,
                        headers=response.headers,
                    )

                return handler

            # FastAPI uses {param} format already
            app.add_api_route(
                route.path,
                make_handler(route),
                methods=[route.method.value],
                tags=route.tags,
                summary=route.description,
            )
